"""Record a narrow local-change pilot and preserve the hypotheses in the graph."""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import hashlib,json,shutil,sys
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'runs/flyvis_local_motion_gate_20261105';sys.path.insert(0,str(ROOT))
from scripts.obsidian_system_problems import load,problem_path
from scripts.obsidian_fundamental_overview import build
from scripts.audit_fundamental_obsidian import audit
def sha(x):return hashlib.sha256(Path(x).read_bytes()).hexdigest()
def main():
 r=json.loads((OUT/'report.json').read_text(encoding='utf-8'));a=json.loads((OUT/'independent_audit.json').read_text(encoding='utf-8'));assert a['passed'] and a['report_sha256']==sha(OUT/'report.json');s=r['summaries'];assert s['local']['n']==48 and s['still']['n']==16
 msg=(f"В предварительном искусственном опыте локальный признак ошибочно признал покой в {s['local']['local_stationary']} из {s['local']['n']} условий движения объекта; прежний глобальный — в {s['local']['global_stationary']} из тех же {s['local']['n']}. Среди {s['still']['n']} условий покоя локальный признак ошибочно сообщил о движении в {s['still']['local_moving']}, глобальный — в {s['still']['global_moving']}. Заранее заданные пороги этой узкой проверки выполнены: {r['checks']}. Порог локального признака определён только по четырём настройочным сценам; оценка на четырёх других сценах. Все эти сцены из обучающей части BDD, отдельные синтетические условия внутри сцены зависимы. Независимо пересчитаны признаки и решения при общем генераторе кадров; код аудита написан после прогона. Это не оценка частоты ошибок на реальном видео и не проверка модели FlyVis или трекера.")
 refs=['runs/flyvis_local_motion_gate_20261105/'+x for x in ('protocol.json','report.json','independent_audit.json')];(OUT/'РЕЗУЛЬТАТ.md').write_text('# Локальный признак движения для FlyVis\n\n'+msg+'\n\nПроверены искусственные прямоугольные объекты и глобальные сдвиги. Слабый контраст, освещение, движущаяся камера с объектом, однотонные и реальные движущиеся сцены этой серией не проверены. Не доказано, что признак безопасен для вычитания смещения. Признак внешний по отношению к FlyVis; ядро не менялось.\n\nИсточники: '+', '.join('`'+x+'`' for x in refs)+'.\n',encoding='utf-8')
 cat=ROOT/'experiments/project_history.json';d=json.loads(cat.read_text(encoding='utf-8'));c=next(x for x in d['experiments'] if x['id']=='flyvis_local_motion_gate_v1');assert c['state']=='planned';c.update(state='completed_positive' if r['preliminary_gate'] else 'completed_negative',done=datetime.now(ZoneInfo('Europe/Moscow')).date().isoformat(),obtained=msg+' Источники: '+', '.join(refs),interpretation='Узкий предварительный критерий локального пиксельного признака выполнен; обобщение на реальные сцены и польза FlyVis не проверены.',decision='Сохранить результат как основание для дальнейшей проверки на условиях, не входивших в пилот; не внедрять как готовое решение.',cannot_claim='Нет результатов полной FlyVis, HOTA, реального движения, меняющегося света, слабого контраста и статистически независимых 48 сцен.');c['acceptance'][0].update(met=bool(r['preliminary_gate'] and a['passed']),evidence=refs[1]+':checks; '+refs[2]);c['evidence'] += [dict(kind='json',ref=x,claim='Результат или независимый пересчёт') for x in refs[1:]];cat.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 prob=ROOT/'experiments/system_problems.json';d=json.loads(prob.read_text(encoding='utf-8'));item=next(x for x in d['problems'] if x['id']=='С7');item['cases'].append(dict(date='2026-11-05',fact=msg,evidence=refs));item['cards'].append(c['id'])
 for x in refs:item['evidence'].append(dict(source=x,sha256=sha(ROOT/x),claim='Локальный признак движения: протокол, результат и пересчёт'))
 prob.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md';raw=plan.read_bytes();marker='## Журнал изменений'.encode();nl=b'\r\n' if marker+b'\r\n' in raw else b'\n';now=datetime.now(ZoneInfo('Europe/Moscow'));entry=f'\n**{now:%d.%m.%Y, %H:%M} MSK** — Предварительная проверка локального движения\n\n{msg} Источники: '+', '.join('`'+x+'`' for x in refs)+'. Проблема С7 остаётся открытой.\n\n';assert raw.count(marker+nl)==1;plan.write_bytes(raw.replace(marker+nl,marker+nl+entry.encode(),1))
 road=ROOT/'FLYVIS_TRACKER_RESEARCH_ROADMAP.md'
 with road.open('a',encoding='utf-8') as f:f.write('\n\n## 05.11.2026 — предварительный локальный признак движения\n\n'+msg+' Источник: `'+refs[1]+'`. С7 открыта.\n')
 vault=ROOT/'ObsidianFlyVis';stage=OUT/'vault_checked';backup=OUT/'vault_before';assert not stage.exists() and not backup.exists();shutil.copytree(vault,stage);shutil.copytree(vault,backup);before={f.relative_to(vault).as_posix():sha(f) for f in vault.rglob('*') if f.is_file()};name=problem_path(next(x for x in load()['problems'] if x['id']=='С7'))+'.md';preserve=[x for x in before if x.endswith('.md') and x!=name];assert build(stage,preserve)==0
 for f in ('.obsidian/graph.json','.graph-visible.json','.generated.json'):shutil.copy2(backup/f,stage/f)
 checked=audit(stage);assert checked['note_count']==55 and checked['hypothesis_node_count']==25 and checked['problem_node_count']==10 and not checked['external_hypothesis_edges'];assert set(before)=={f.relative_to(stage).as_posix() for f in stage.rglob('*') if f.is_file()};changed=[f for f,h in before.items() if sha(stage/f)!=h];assert changed==[name] and all(sha(vault/f)==h for f,h in before.items());shutil.copy2(stage/name,vault/name);done=audit(vault);assert done['hashes']==checked['hashes'];done.update(changed_files=changed,added_files=[],deleted_files=[],protected_hypotheses_byte_exact=True);(OUT/'graph_audit.json').write_text(json.dumps(done,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Recorded and graph checked')
if __name__=='__main__':main()
